CREATE OR REPLACE FUNCTION public.base_org_chart_read() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND status='Đang hoạt động') THEN RAISE EXCEPTION 'Chỉ nhân sự đang hoạt động được xem sơ đồ tổ chức.';END IF;RETURN jsonb_build_object('server_now',now(),'units',coalesce((SELECT jsonb_agg(u) FROM jsonb_array_elements(private.base_config()->'units') u),'[]'::jsonb),'titles',coalesce((SELECT jsonb_agg(t) FROM jsonb_array_elements(private.base_config()->'titles') t),'[]'::jsonb),'members',coalesce((SELECT jsonb_agg(jsonb_build_object('user_id',p.id,'name',p.full_name,'unit_id',m->>'unit_id','title_id',m->>'title_id','duties',m->>'duties','active',coalesce((m->>'active')::boolean,false),'starts_at',m->>'starts_at','ends_at',m->>'ends_at')) FROM jsonb_array_elements(private.base_config()->'memberships') m JOIN profiles p ON p.id::text=m->>'user_id'),'[]'::jsonb));END $$;REVOKE ALL ON FUNCTION public.base_org_chart_read() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.base_org_chart_read() TO authenticated,service_role;